int order_save(sqlite3 *db, const Order *o) {
    sqlite3_exec(db, "BEGIN", 0, 0, 0);
    execf(db, "DELETE FROM order_line WHERE order_id=?1", o->id);  /* replace the set */
    for (size_t i = 0; i < o->line_count; i++)
        execf(db, "INSERT INTO order_line(order_id, sku, qty) VALUES(?1,?2,?3)",
              o->id, o->lines[i].sku, o->lines[i].qty);            /* no line identity */
    return sqlite3_exec(db, "COMMIT", 0, 0, 0);
}
